-- =============================================================================
-- IMPORT DATA KONTEN DARI LARAVEL (MySQL -> Supabase/Postgres)
-- =============================================================================
-- File ini dibuat oleh scripts/import-laravel-data.py.
-- Jalankan SETELAH 0001_init.sql dan 0002_storage.sql.
--
-- Catatan:
--   * id dipertahankan agar relasi antar tabel tetap konsisten.
--   * aman dijalankan ulang karena memakai `on conflict (id) do nothing`.
--   * tabel `users` tidak diimpor; buat admin lewat Supabase Auth.
--   * urutan insert mengikuti dependensi foreign key.
-- =============================================================================

begin;



-- categories (8 baris)
on conflict (id) do nothing;

-- services (5 baris)
on conflict (id) do nothing;

-- service_areas (10 baris)
on conflict (id) do nothing;

-- testimonials (5 baris)
on conflict (id) do nothing;

-- equipment (11 baris)
on conflict (id) do nothing;

-- equipment_images (11 baris)
on conflict (id) do nothing;

-- projects (5 baris)
on conflict (id) do nothing;

-- project_images (5 baris)
on conflict (id) do nothing;

-- blog_posts (5 baris)
on conflict (id) do nothing;

-- faqs (10 baris)
on conflict (id) do nothing;

-- Lanjutkan identity sequence (id eksplisit dipakai di atas).
select setval(pg_get_serial_sequence('public.categories', 'id'), coalesce((select max(id) from public.categories), 1), true);
select setval(pg_get_serial_sequence('public.services', 'id'), coalesce((select max(id) from public.services), 1), true);
select setval(pg_get_serial_sequence('public.service_areas', 'id'), coalesce((select max(id) from public.service_areas), 1), true);
select setval(pg_get_serial_sequence('public.testimonials', 'id'), coalesce((select max(id) from public.testimonials), 1), true);
select setval(pg_get_serial_sequence('public.equipment', 'id'), coalesce((select max(id) from public.equipment), 1), true);
select setval(pg_get_serial_sequence('public.equipment_images', 'id'), coalesce((select max(id) from public.equipment_images), 1), true);
select setval(pg_get_serial_sequence('public.projects', 'id'), coalesce((select max(id) from public.projects), 1), true);
select setval(pg_get_serial_sequence('public.project_images', 'id'), coalesce((select max(id) from public.project_images), 1), true);
select setval(pg_get_serial_sequence('public.blog_posts', 'id'), coalesce((select max(id) from public.blog_posts), 1), true);
select setval(pg_get_serial_sequence('public.faqs', 'id'), coalesce((select max(id) from public.faqs), 1), true);

commit;
