insert into public.services (id, title, slug, description, body, icon, image, is_active, created_at, updated_at) values
    (1, 'Penyewaan Alat Berat', 'penyewaan-alat-berat', 'Layanan penyewaan berbagai jenis alat berat untuk proyek konstruksi, pertambangan, dan industri dengan armada yang terawat dan berkualitas.', '<h3>Layanan Penyewaan Alat Berat</h3><p>Kami menyediakan berbagai jenis alat berat untuk mendukung kelancaran proyek Anda. Armada kami terdiri dari excavator, bulldozer, crane, forklift, dump truck, compactor, dan berbagai alat berat lainnya yang siap digunakan kapan saja.</p><p>Setiap unit alat berat kami menjalani perawatan rutin dan pemeriksaan menyeluruh sebelum disewakan untuk memastikan performa optimal dan keamanan operasional.</p><h4>Keunggulan Layanan Kami:</h4><ul><li>Armada lengkap dan terawat</li><li>Operator berpengalaman dan bersertifikasi</li><li>Pengiriman tepat waktu</li><li>Dukungan teknis 24/7</li><li>Harga kompetitif</li></ul>', 'fa-solid fa-tractor', NULL, true, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-07T03:18:06+00:00'::timestamptz),
    (2, 'Operator & Tenaga Ahli', 'operator-tenaga-ahli', 'Menyediakan operator profesional dan tenaga ahli bersertifikasi untuk mengoperasikan alat berat dengan aman dan efisien.', '<h3>Operator & Tenaga Ahli Bersertifikasi</h3><p>Kami menyediakan operator berpengalaman yang telah memiliki sertifikasi resmi dari instansi terkait. Setiap operator kami telah melalui pelatihan ketat dan memiliki jam terbang tinggi.</p>', 'fa-solid fa-helmet-safety', NULL, true, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-06T11:40:15+00:00'::timestamptz),
    (3, 'Perawatan & Perbaikan', 'perawatan-perbaikan', 'Layanan perawatan dan perbaikan alat berat oleh teknisi handal dengan suku cadang original untuk memastikan alat berat tetap dalam kondisi prima.', '<h3>Layanan Perawatan & Perbaikan</h3><p>Tim teknisi kami siap menangani perawatan rutin hingga perbaikan besar alat berat Anda. Kami menggunakan suku cadang original dan peralatan diagnostik modern.</p>', 'fa-solid fa-wrench', NULL, true, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-06T11:40:15+00:00'::timestamptz),
    (4, 'Konsultasi Proyek', 'konsultasi-proyek', 'Layanan konsultasi untuk membantu Anda memilih alat berat yang tepat sesuai kebutuhan dan anggaran proyek Anda.', '<h3>Konsultasi Proyek</h3><p>Tim konsultan kami siap membantu Anda menentukan alat berat yang paling sesuai dengan kebutuhan proyek, mulai dari pemilihan jenis, spesifikasi, hingga estimasi biaya operasional.</p>', 'fa-solid fa-handshake', NULL, true, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-06T11:40:15+00:00'::timestamptz),
    (5, 'Logistik & Mobilisasi', 'logistik-mobilisasi', 'Layanan pengiriman dan mobilisasi alat berat ke lokasi proyek di seluruh Indonesia dengan aman dan tepat waktu.', '<h3>Logistik & Mobilisasi</h3><p>Kami menangani pengiriman alat berat ke lokasi proyek Anda di mana pun berada. Dengan armada transportasi khusus dan tim logistik yang berpengalaman, alat berat Anda akan tiba dengan aman dan tepat waktu.</p>', 'fa-solid fa-truck-fast', NULL, true, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-06T11:40:15+00:00'::timestamptz)
