insert into public.testimonials (id, client_name, client_position, company, photo, content, rating, is_active, is_featured, created_at, updated_at) values
    (1, 'Bambang Supriyadi', 'Project Manager', 'PT Wijaya Karya Tbk', NULL, 'AlatBerat memberikan layanan penyewaan alat berat yang sangat profesional. Armada mereka terawat dengan baik dan pengiriman selalu tepat waktu. Sangat merekomendasikan!', 5, true, true, '2026-07-08T09:18:43+00:00'::timestamptz, '2026-07-08T13:47:42+00:00'::timestamptz),
    (2, 'Dewi Sartika', 'Site Manager', 'PT PP Tbk', NULL, 'Kami sudah bekerjasama dengan AlatBerat untuk 3 proyek besar. Kualitas alat dan dukungan teknisnya luar biasa. Operator yang dikirim juga sangat berpengalaman.', 5, true, true, '2026-07-08T09:18:43+00:00'::timestamptz, '2026-07-08T13:47:47+00:00'::timestamptz),
    (3, 'Andi Hakim', 'Owner', 'CV Karya Mandiri', NULL, 'Harga sewa yang kompetitif dengan kualitas alat yang bagus. Proses sewa juga mudah dan cepat. Sangat membantu proyek kami.', 4, true, true, '2026-07-08T09:18:43+00:00'::timestamptz, '2026-07-08T13:47:52+00:00'::timestamptz),
    (4, 'Rina Marlina', 'Procurement Manager', 'PT Adhi Karya Tbk', NULL, 'Tim AlatBerat sangat responsif dalam menangani kebutuhan alat berat kami. Bahkan untuk permintaan mendadak, mereka selalu bisa mengakomodasi.', 5, true, true, '2026-07-08T09:18:43+00:00'::timestamptz, '2026-07-08T13:47:57+00:00'::timestamptz),
    (5, 'Hendra Gunawan', 'Direktur', 'PT Bangun Cipta', NULL, 'Pelayanan after sales yang sangat baik. Tim teknis selalu siap membantu jika ada masalah dengan alat. Recommended untuk penyewaan alat berat.', 4, true, true, '2026-07-08T09:18:43+00:00'::timestamptz, '2026-07-08T13:48:02+00:00'::timestamptz)
