    (1, 'Proyek Pembangunan Jalan Tol Trans Jawa', 'proyek-pembangunan-jalan-tol-trans-jawa', 'Penyewaan alat berat untuk pembangunan jalan tol di jalur Pantai Utara Jawa dengan durasi 18 bulan.', NULL, 'PT Jasamarga Tollroad Operator', 'Pantai Utara Jawa', NULL, 'Excavator, Bulldozer, Dump Truck, Compactor', '2024-01-15'::date, '2025-07-15'::date, 'https://imgcdn.espos.id/@espos/images/2025/07/20250729175601-antarafoto-progres-pembangunan-ruas-tol-probowangi-1753786531.jpg?quality=60', NULL, true, true, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-08T12:19:24+00:00'::timestamptz),
    (2, 'Proyek Tambang Batubara Kalimantan Timur', 'proyek-tambang-batubara-kalimantan-timur', 'Penyediaan alat berat untuk operasional tambang batubara di Kalimantan Timur dengan kapasitas produksi tinggi.', NULL, 'PT Bumi Resources Tbk', 'Kalimantan Timur', NULL, 'Bulldozer D375A, Excavator PC200, Dump Truck Hino', '2024-03-01'::date, '2026-02-28'::date, 'https://images-tm.tempo.co/all/2024/08/07/867173/867173_1200.jpg', NULL, true, true, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-08T12:22:24+00:00'::timestamptz),
    (3, 'Pembangunan Gedung Perkantoran Jakarta CBD', 'pembangunan-gedung-perkantoran-jakarta-cbd', 'Penyewaan crane dan alat berat untuk konstruksi gedung 40 lantai di kawasan bisnis Jakarta.', NULL, 'PT Agung Podomoro Land', 'Jakarta Selatan', NULL, 'Crane Mobile 50 Ton, Excavator, Concrete Mixer', '2024-06-01'::date, '2025-12-31'::date, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTGF-w-ARAVhZhp0_IIn7459RWU3aBGtGd4PCXOzBmZDan2hLVUQsPzyzBL&s=10', NULL, true, true, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-08T12:23:15+00:00'::timestamptz),
    (4, 'Proyek Pabrik Smelter Nikel Sulawesi', 'proyek-pabrik-smelter-nikel-sulawesi', 'Penyediaan alat berat untuk pembangunan pabrik smelter nikel di Sulawesi Tengah.', NULL, 'PT Vale Indonesia Tbk', 'Sulawesi Tengah', NULL, 'Excavator, Crane Crawler, Bulldozer, Dump Truck', '2024-08-15'::date, NULL, 'https://images.bisnis.com/posts/2023/03/31/1642361/DJI_0024.jpg', NULL, false, true, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-08T12:24:57+00:00'::timestamptz),
