insert into public.blog_posts (id, title, slug, excerpt, body, image, author, tags, is_published, published_at, created_at, updated_at) values
    (1, 'Tips Memilih Alat Berat yang Tepat untuk Proyek Konstruksi', 'tips-memilih-alat-berat-yang-tepat-untuk-proyek-konstruksi', 'Panduan lengkap memilih alat berat yang sesuai dengan kebutuhan proyek konstruksi Anda agar efisien dan hemat biaya.', '<h3>Pendahuluan</h3><p>Memilih alat berat yang tepat adalah keputusan krusial dalam setiap proyek konstruksi. Pemilihan yang salah dapat mengakibatkan pembengkakan biaya, keterlambatan proyek, bahkan kegagalan struktural.</p><h3>Faktor-faktor yang Perlu Dipertimbangkan</h3><p>1. Jenis Pekerjaan2. Kondisi Medan3. Kapasitas yang Dibutuhkan4. Durasi Proyek5. Anggaran</p><h3>Kesimpulan</h3><p>Konsultasikan dengan tim ahli kami untuk mendapatkan rekomendasi alat berat yang paling sesuai dengan kebutuhan proyek Anda.</p>', 'https://psualatberat.com/wp-content/uploads/2025/07/operator-excavator.png', 'Tim AlatBerat', '["konstruksi","tips","alat berat"]'::jsonb, true, '2025-12-15T01:00:00+00:00'::timestamptz, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-08T13:05:51+00:00'::timestamptz),
    (2, 'Perawatan Rutin Alat Berat untuk Memperpanjang Umur Mesin', 'perawatan-rutin-alat-berat-untuk-memperpanjang-umur-mesin', 'Ketahui pentingnya perawatan rutin alat berat dan cara-cara sederhana yang bisa dilakukan untuk memperpanjang usia mesin.', '<h3>Mengapa Perawatan Rutin Penting?</h3><p>Perawatan rutin adalah investasi jangka panjang untuk alat berat Anda. Dengan perawatan yang tepat, umur mesin dapat diperpanjang hingga 30% lebih lama.</p><h3>Jadwal Perawatan</h3><p>Kami merekomendasikan jadwal perawatan rutin setiap 250 jam operasi untuk pergantian oli dan filter.</p>', 'https://static.wixstatic.com/media/46d697_4dbc83f2340a4410a7b405911281013d~mv2.png/v1/fill/w_568,h_318,al_c,q_85,usm_0.66_1.00_0.01,enc_avif,quality_auto/46d697_4dbc83f2340a4410a7b405911281013d~mv2.png', 'Tim AlatBerat', '["perawatan","alat berat","tips"]'::jsonb, true, '2026-01-20T02:30:00+00:00'::timestamptz, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-08T13:06:28+00:00'::timestamptz),
    (3, 'Keuntungan Sewa Alat Berat Dibanding Beli', 'keuntungan-sewa-alat-berat-dibanding-beli', 'Analisis lengkap mengapa menyewa alat berat lebih menguntungkan daripada membeli untuk banyak jenis proyek.', '<h3>Mengapa Sewa Lebih Baik?</h3><p>Menyewa alat berat memberikan fleksibilitas yang tidak bisa diberikan oleh pembelian. Anda bisa menyesuaikan jenis dan jumlah alat sesuai kebutuhan proyek.</p><h3>Keuntungan Utama:</h3><p>1. Tidak perlu modal besar di awal2. Bebas biaya perawatan3. Armada selalu terbaru4. Fleksibilitas tinggi</p>', 'https://psualatberat.com/wp-content/uploads/2023/12/Fungsi-Alat-Berat-1024x683.jpg', 'Tim AlatBerat', '["sewa","alat berat","bisnis"]'::jsonb, true, '2026-03-10T03:00:00+00:00'::timestamptz, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-08T13:07:00+00:00'::timestamptz),
    (4, 'Standar Keselamatan Operasi Alat Berat di Indonesia', 'standar-keselamatan-operasi-alat-berat-di-indonesia', 'Panduan mengenai standar keselamatan kerja dalam pengoperasian alat berat yang berlaku di Indonesia.', '<h3>Regulasi Keselamatan</h3><p>Pemerintah Indonesia telah menetapkan berbagai regulasi terkait keselamatan operasi alat berat yang wajib dipatuhi oleh semua pihak.</p>', 'https://www.safetysign.co.id/image-upload/shutterstock_210129415-res.jpg', 'Tim AlatBerat', '["keselamatan","regulasi","K3"]'::jsonb, true, '2026-04-05T00:45:00+00:00'::timestamptz, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-08T13:07:37+00:00'::timestamptz),
    (5, 'Inovasi Teknologi Alat Berat 2026', 'inovasi-teknologi-alat-berat-2026', 'Perkembangan teknologi terbaru dalam dunia alat berat yang akan mengubah cara kerja industri konstruksi dan pertambangan.', '<h3>Teknologi Terbaru</h3><p>Dunia alat berat terus berkembang dengan teknologi AI, IoT, dan otomatisasi yang semakin canggih.</p>', 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEghe_cxSk_f7nn6mAnL8qdKyS0tXknydC-gWK9Y9RMVODenXZ3dpNd29Y52DNRvUGp1Ypv4mV93nPCcCADp4xcsFx8rgUPi6kAPCwFKipNXUkVBdN7WYuIWADk_lGfQpBup6RrzmFgWTCLqQG8gSklIC4unHlQwqAFz0AmyP8uCDYUwWHHAbkLVkVrTdhDP/s2560/WhatsApp%20Image%202026-06-29%20at%2015.24.01.jpeg', 'Tim AlatBerat', '["teknologi","inovasi","2026"]'::jsonb, true, '2026-07-08T13:10:29+00:00'::timestamptz, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-08T13:10:29+00:00'::timestamptz)
insert into public.faqs (id, question, answer, category, sort_order, is_active, created_at, updated_at) values
    (1, 'Berapa minimal durasi sewa alat berat?', 'Minimal durasi sewa alat berat kami adalah 1 hari (8 jam kerja). Untuk proyek jangka panjang, kami menyediakan paket khusus dengan harga lebih kompetitif.', 'Penyewaan', 1, true, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-06T11:40:15+00:00'::timestamptz),
    (2, 'Apakah alat berat disertai operator?', 'Ya, setiap penyewaan alat berat dapat disertai operator berpengalaman dan bersertifikasi. Biaya operator sudah termasuk dalam paket sewa tertentu atau dapat ditambahkan sesuai kebutuhan.', 'Penyewaan', 2, true, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-06T11:40:15+00:00'::timestamptz),
    (3, 'Bagaimana cara pemesanan?', 'Pemesanan dapat dilakukan melalui website, telepon, WhatsApp, atau datang langsung ke kantor kami. Tim kami akan membantu Anda memilih alat berat yang sesuai dan memproses penyewaan dengan cepat.', 'Penyewaan', 3, true, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-06T11:40:15+00:00'::timestamptz),
    (4, 'Apakah ada biaya pengiriman?', 'Ya, biaya pengiriman alat berat ke lokasi proyek dihitung terpisah berdasarkan jarak dan jenis alat. Kami akan memberikan quote lengkap termasuk biaya pengiriman sebelum transaksi.', 'Biaya', 4, true, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-06T11:40:15+00:00'::timestamptz),
    (5, 'Bagaimana jika alat berat rusak saat disewa?', 'Jika kerusakan terjadi karena pemakaian normal, kami akan menangani perbaikan tanpa biaya tambahan. Namun, jika kerusakan disebabkan oleh kelalaian penyewa, biaya perbaikan akan ditanggung penyewa.', 'Layanan', 5, true, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-06T11:40:15+00:00'::timestamptz),
    (6, 'Apakah tersedia layanan perawatan alat berat?', 'Ya, kami menyediakan layanan perawatan dan perbaikan alat berat untuk semua merek. Tim teknisi kami siap melakukan perawatan rutin maupun perbaikan besar.', 'Layanan', 6, true, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-06T11:40:15+00:00'::timestamptz),
    (7, 'Wilayah mana saja yang dilayani?', 'Kami melayani seluruh wilayah Indonesia, dengan kantor cabang di Jakarta, Bandung, Surabaya, Medan, Makassar, Balikpapan, dan kota-kota besar lainnya.', 'Layanan', 7, true, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-06T11:40:15+00:00'::timestamptz),
    (8, 'Pembayaran menggunakan apa saja?', 'Kami menerima pembayaran melalui transfer bank (BCA, Mandiri, BRI, BNI), kartu kredit, dan giro. Untuk proyek jangka panjang, tersedia sistem termin pembayaran.', 'Biaya', 8, true, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-06T11:40:15+00:00'::timestamptz),
    (9, 'Apakah saya bisa melihat alat berat sebelum menyewa?', 'Tentu saja. Anda dapat mengunjungi depot kami untuk melihat langsung kondisi alat berat yang akan disewa. Kami juga dapat mengirimkan foto dan video kondisi alat terkini.', 'Penyewaan', 9, true, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-06T11:40:15+00:00'::timestamptz),
    (10, 'Berapa deposit yang harus dibayarkan?', 'Deposit sebesar 20-30% dari total biaya sewa dikenakan tergantung jenis alat dan durasi sewa. Deposit akan dikembalikan setelah alat dikembalikan dalam kondisi baik.', 'Biaya', 10, true, '2026-07-06T11:40:15+00:00'::timestamptz, '2026-07-06T11:40:15+00:00'::timestamptz)
